use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // `requires len(question) <= 512` holds of every input by contract;
        // enforce it defensively so a violation surfaces as a value, not UB.
        if ctx.question.len() > 512 {
            return ResponseResult::Error(LlmError {
                message: "question exceeds 512 bytes".to_string(),
            });
        }

        let system = "You are a customer support agent. When the knowledge base \
                      would help, ask to invoke the `lookup` tool; otherwise \
                      answer the user's question directly and concisely.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\nKnown context:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // The tool-orchestration loop. `tool-llm` offers exactly `generate`,
        // and the only tool in scope is `lookup` via the `kb-read` handle.
        const MAX_ROUNDS: usize = 4;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not in scope: {}", req.tool),
                        });
                    }
                    let results = kb_read::lookup(&req.query);
                    prompt.push_str("\n\nTool result — lookup(");
                    prompt.push_str(&req.query);
                    prompt.push_str("):\n");
                    if results.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for r in &results {
                            prompt.push_str("- ");
                            prompt.push_str(r);
                            prompt.push('\n');
                        }
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool orchestration did not converge".to_string(),
        })
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
```

